static boolean runWithTimeout(ExecutorService pool, long timeoutSeconds) throws InterruptedException {
    pool.shutdown();
    boolean ok = pool.awaitTermination(timeoutSeconds, TimeUnit.SECONDS);
    if (!ok) pool.shutdownNow();
    return ok;
}
