List<String> dane = List.of("a","b","c","d","e","f","g","h","i","j");
List<String> wynik = Collections.synchronizedList(new ArrayList<>());
CountDownLatch latch = new CountDownLatch(10);
ExecutorService stage1 = Executors.newFixedThreadPool(2);
for (String s : dane) stage1.submit(() -> { wynik.add(s.toUpperCase()); latch.countDown(); });
latch.await(5, TimeUnit.SECONDS);
ExecutorService stage2 = Executors.newFixedThreadPool(2);
Future<String> agregat = stage2.submit(() -> String.join("", wynik));
System.out.println(agregat.get());
stage1.shutdown(); stage1.awaitTermination(5, TimeUnit.SECONDS);
stage2.shutdown(); stage2.awaitTermination(5, TimeUnit.SECONDS);

Semaphore semaphore = new Semaphore(2);
AtomicInteger aktywne = new AtomicInteger(0);
ExecutorService pool = Executors.newFixedThreadPool(5);
for (int i=1;i<=10;i++) { int id=i; pool.submit(() -> { try { semaphore.acquire(); int a=aktywne.incrementAndGet(); System.out.println("zadanie-"+id+": aktywne="+a); Thread.sleep(100); aktywne.decrementAndGet(); } catch (Exception e) {} finally { semaphore.release(); } }); }
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);

