Deque<Runnable> kolejka = new ArrayDeque<>();
Runnable POISON_PILL = () -> {};
Runnable worker = () -> { while (true) { Runnable zadanie; synchronized (kolejka) { while (kolejka.isEmpty()) { try { kolejka.wait(); } catch (Exception e) {} } zadanie = kolejka.poll(); } if (zadanie == POISON_PILL) break; zadanie.run(); } };
Thread w1 = new Thread(worker), w2 = new Thread(worker);
w1.start(); w2.start();
synchronized (kolejka) { for (int i=1;i<=5;i++) { int id=i; kolejka.add(() -> System.out.println("zadanie-"+id)); } kolejka.add(POISON_PILL); kolejka.add(POISON_PILL); kolejka.notifyAll(); }
w1.join(5_000); w2.join(5_000);

