AtomicInteger sukces = new AtomicInteger(0), porazka = new AtomicInteger(0);
CountDownLatch latch = new CountDownLatch(25);
ExecutorService pool = Executors.newFixedThreadPool(4);
for (int i=0;i<25;i++) { int id=i; pool.submit(() -> { try { if (id % 5 == 4) throw new RuntimeException("blad zamowienia "+id); sukces.incrementAndGet(); } catch (RuntimeException e) { porazka.incrementAndGet(); } finally { latch.countDown(); } }); }
latch.await(5, TimeUnit.SECONDS);
System.out.println("sukces="+sukces.get()+" porazka="+porazka.get());
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);
